// ValueSource defines model for ValueSource.
type ValueSource struct {
	// Kind `builtin`, `rest` and `cel` are defined where they are used;
	// `library` names an entry of the form library (ADR-0043). A form
	// library entry is `rest` or `cel`.
	Kind ValueSourceKind `json:"kind"`

	// Name For `library`: the key of a form library entry that is a
	// source (ADR-0043); `params` gives its parameters.
	//
	// For `builtin`: `vsphere.clusters`, `vsphere.datastores`,
	// `vsphere.networks`, `vsphere.templates`, `vsphere.folders`
	// (the VM folders of the datacenters the project's placement
	// uses in the environment, by path, each under its parent
	// folder; checked on submit),
	// `ipam.subnets`, `ipam.next_free_address`, `dns.zones`,
	// `awx.inventories`, `awx.credentials`, `naming.preview`,
	// `rvav.templates` and `rvav.sizes` (what is offered to the
	// project and environment; ADR-0020), `nsx.segments`
	// (`tier1` param), `nsx.tier1s`, `nsx.groups` (as `nsx:<ID>`)
	// and `nsx.services` (ADR-0028), and rvav's own records, which
	// the `project`, `user`, `deployment` and `vsphere_vm` widgets
	// always take their choices from: `rvav.projects` (those the
	// requester may request in, by ID), `rvav.users` (people, by
	// ID; `search` finds them by name or email, or one by ID),
	// `rvav.deployments` (the project's, not deleted, by ID; the
	// `item` param keeps one catalog item's, by slug) and
	// `rvav.vms` (their VMs, by name; the `deployment` param keeps
	// one deployment's). The server refuses, on submit, a value
	// the requester couldn't have picked.
	//
	//
	// Examples: vsphere.datastores
	Name *string `json:"name,omitempty"`

	// Params Source parameters. String values may reference inputs, for example `${inputs.cluster}`.
	// For `rest`: `url` (on a host REST value sources may call: Allowed hosts, or RVAV_REST_SOURCE_HOSTS), `method` (GET or POST), `body`,
	// `secret` (a stored secret's name), `items` (JSONPath to the list), `value`, `label`,
	// `meta` and `parent` (JSONPath in each item), `cache_seconds`. For `cel`: `options` (an
	// expression giving a list of strings or of {value, label, meta, parent}) or `value`.
	// For `library`: a CEL expression per parameter of the entry, over what form rules read and
	// `search`, for example `{"environment": "inputs.environment"}`; the entry's templates read
	// them as `${params.x}`, its expressions as `params.x`.
	//
	// On a field that takes one value rather than a choice (`text`,
	// `textarea`, `number`, `slider`, `date`, `datetime`, `toggle`),
	// a `rest`, `cel` or `library` source gives the field its default (see
	// `UiRules.default`), as the input's type takes it: a text input
	// takes a number as its digits. A `rest` source's is what `value`
	// finds in the first item `items` finds (the answer's first item
	// when it is a list, or the answer itself, without `items`); a
	// `cel` source's is its `value`. On a `computed` field, it gives
	// the field's value, which the server works out again on preview
	// and submit. A source that fails gives no default. The field's
	// `depends_on` names the inputs its source reads: those with a
	// source are worked out first.
	Params *map[string]interface{} `json:"params,omitempty"`

	// Search For `rest` and `cel`: the source finds options by the text the
	// requester types in a `search` field, which its `url` or `body`
	// reads as `${search}` and its expressions as `search`. Without
	// it, rvav keeps the options whose value, label or detail
	// contains the text. On submit, a `search` field's value must be
	// one its source finds when searched for that value.
	Search *bool `json:"search,omitempty"`

	// Version For `library`, the version of the entry `name` the field uses.
	Version *int `json:"version,omitempty"`
}

